// Some portions generated by Codex
// @ts-check
const { test, expect } = require('@playwright/test');
const { createSeededRepository, deleteRepository, repositoryPageUrl, serverBaseUrl, workbenchBaseUrl,
    uniqueRepositoryId, waitForRoute, setQueryEditor } = require('./workbench-test-helpers.js');

const repositoryId = uniqueRepositoryId('graph-server-scope');
const serverA = serverBaseUrl();
const serverB = process.env.RDF4J_SECOND_SERVER_BASE_URL;

test.beforeAll(async ({request}) => {
    test.skip(!serverB, 'Two real RDF4J servers are required for server identity isolation.');
    for (const [server, name] of [[serverA,'a'],[serverB,'b']]) {
        await createSeededRepository(request, server, repositoryId, {graphs:[]});
        const loaded = await request.post(`${server}/repositories/${repositoryId}/statements`, {
            headers:{'Content-Type':'text/turtle'}, data:`<urn:${name}> <urn:property> <urn:${name}-target> . <urn:${name}> <http://www.w3.org/2000/01/rdf-schema#label> "Server ${name.toUpperCase()} source" . <urn:${name}-target> <http://www.w3.org/2000/01/rdf-schema#label> "Server ${name.toUpperCase()} target" .`
        });
        expect(loaded.ok()).toBeTruthy();
    }
});
test.afterAll(async ({request}) => {
    if (!serverB) return;
    await deleteRepository(request, serverA, repositoryId);
    await deleteRepository(request, serverB, repositoryId);
});

async function selectServer(context, server) {
    await context.addCookies([{name:'workbench-server',value:server,url:workbenchBaseUrl()+'/'}]);
}
async function graph(page) {
    await page.goto(repositoryPageUrl(repositoryId,'graph'));
    await waitForRoute(page,'graph');
    await expect(page.locator('.graph-explorer')).toHaveCount(1);
}
async function load(page) {
    await page.getByRole('button',{name:'Load 100 statements'}).click();
    await expect(page.locator('.graph-node')).toHaveCount(2);
}

test('same repository keeps distinct workspaces and queues on two servers and restores on switching back', async ({page,context}) => {
    await page.setViewportSize({width:1440,height:900});
    const errors=[];
    page.on('pageerror',error=>errors.push(error.message));
    await selectServer(context,serverA);
    await graph(page);
    const identityA=await page.locator('#workbench-app').getAttribute('data-workbench-server-identity');
    expect(identityA).toMatch(/^sha256:/);
    await load(page);
    await expect(page.locator('.graph-node[aria-label^="Server A source."]')).toHaveCount(1);
    await page.locator('#navigation a[href$="summary"]').first().click();
    await waitForRoute(page,'summary');

    await selectServer(context,serverB);
    await graph(page);
    const identityB=await page.locator('#workbench-app').getAttribute('data-workbench-server-identity');
    expect(identityB).not.toBe(identityA);
    await expect(page.getByText('The graph is empty',{exact:true})).toBeVisible();
    await load(page);
    await expect(page.locator('.graph-node[aria-label^="Server B source."]')).toHaveCount(1);
    await expect(page.locator('.graph-node[aria-label^="Server A source."]')).toHaveCount(0);
    await page.locator('#navigation a[href$="summary"]').first().click();
    await waitForRoute(page,'summary');

    await selectServer(context,serverA);
    await graph(page);
    await expect(page.locator('.graph-node[aria-label^="Server A source."]')).toHaveCount(1);
    await expect(page.locator('.graph-node[aria-label^="Server B source."]')).toHaveCount(0);
    const queueA=`rdf4j-workbench-graph-additions:${JSON.stringify(['repository-v2',new URL(workbenchBaseUrl()).pathname,identityA,repositoryId])}`;
    const queueB=`rdf4j-workbench-graph-additions:${JSON.stringify(['repository-v2',new URL(workbenchBaseUrl()).pathname,identityB,repositoryId])}`;
    const other=await context.newPage();
    await other.goto(repositoryPageUrl(repositoryId,'summary'));
    await other.evaluate(([key])=>localStorage.setItem(key,JSON.stringify([{kind:'statement',subject:'<urn:queued-b>',predicate:'<urn:property>',object:'<urn:b-target>'}])),[queueB]);
    await expect(page.locator('.graph-node').filter({has:page.locator('text',{hasText:/queued[ -]b/})})).toHaveCount(0);
    await other.evaluate(([key])=>localStorage.setItem(key,JSON.stringify([{kind:'statement',subject:'<urn:queued-a>',predicate:'<urn:property>',object:'<urn:a-target>'}])),[queueA]);
    await expect(page.locator('.graph-node').filter({has:page.locator('text',{hasText:/queued[ -]a/})})).toHaveCount(1);
    await other.close();
    await page.screenshot({path:'/tmp/workbench-graph-server-a-restored.png'});
    expect(errors).toEqual([]);
});

test('a cookie change in another tab refuses new-server query results in the open workspace', async ({page,context}) => {
    await selectServer(context,serverA);
    await graph(page);
    await selectServer(context,serverB);
    await page.getByRole('button',{name:'Load 100 statements'}).click();
    await expect(page.locator('.graph-explorer')).toContainText(/server connection changed/i);
    await expect(page.locator('.graph-node[aria-label^="Server B source."]')).toHaveCount(0);
});

test('the standalone developer mount resolves identity before loading persisted data', async ({page,context}) => {
    const devUrl=process.env.RDF4J_GRAPH_DEV_URL;
    test.skip(!devUrl,'Vite development server is required for standalone mount verification.');
    await context.addCookies([{name:'workbench-server',value:serverA,url:new URL(devUrl).origin+'/'}]);
    await page.goto(`${devUrl}?repository=${repositoryId}`);
    await expect(page.getByRole('button',{name:'Load 100 statements'})).toBeVisible();
    await load(page);
    await expect(page.locator('.graph-node[aria-label^="Server A source."]')).toHaveCount(1);
});


test('Query preserves same-server results and revalidates before cross-tab server restoration', async ({page,context}) => {
    await selectServer(context,serverA);
    await page.goto(repositoryPageUrl(repositoryId,'query'));
    await waitForRoute(page,'query');
    await setQueryEditor(page,'SELECT ?source WHERE { ?source <urn:property> ?target }');
    let executions=0;
    page.on('request',request=>{if(request.method()==='POST'&&request.url().includes('/query')&&/action=exec/.test(request.postData()||''))executions++;});
    await page.locator('#exec').click();
    await expect(page.locator('#query-results .query-result-status')).toContainText('1 row · complete');
    const originalRows=await page.locator('#query-results table.data tbody').innerText();
    await page.locator('#navigation a[href$="graph"]').first().click();
    await waitForRoute(page,'graph');
    await page.locator('#navigation a[href$="query"]').first().click();
    await waitForRoute(page,'query');
    await expect(page.locator('#query-results table.data tbody')).toHaveText(originalRows);
    expect(executions).toBe(1);

    await page.locator('#navigation a[href$="graph"]').first().click();
    await waitForRoute(page,'graph');
    const other=await context.newPage();
    await other.goto(repositoryPageUrl(repositoryId,'summary'));
    await selectServer(context,serverB);
    await page.locator('#navigation a[href$="query"]').first().click();
    await waitForRoute(page,'query');
    await expect(page.locator('#query-results .query-result-layout')).toHaveCount(0);
    expect(executions).toBe(1);
    await selectServer(context,serverA);
    await page.locator('#navigation a[href$="graph"]').first().click();
    await waitForRoute(page,'graph');
    await page.locator('#navigation a[href$="query"]').first().click();
    await waitForRoute(page,'query');
    await expect(page.locator('#query-results table.data tbody')).toHaveText(originalRows);
    expect(executions).toBe(1);
    await other.close();
});
